rule.definition:
if(
  /*SUBMIT AND HR REVIEW*/
  index(ri!nomination, "isHRReview", toboolean(null)) = true,
  and(
    /*AQR 1 OR 2 */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(index(ri!nomination, "isAQR1or2", toboolean({}))),
    /*CANDIDATE GOOD STANDING*/
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(index(ri!nomination, "isCandidateGoodStanding", toboolean({}))),
    /*ADDITIONAL VETTING*/
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(index(ri!nomination, "isVettingRequired", toboolean({}))),
    /*Expected MD Promotion Date per latest available pipeline*/
    if(
      or(
        index(ri!nomination,"subPositionTypeId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454622",
        index(ri!nomination,"subPositionTypeId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454629"
      ),
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(index(ri!nomination, "mdPromotionDateHR", null)),
      true
    ),
    /*Expected Partner Promotion Date per latest available pipeline*/
    if(
      or(
        index(ri!nomination,"subPositionTypeId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454622",
        index(ri!nomination,"subPositionTypeId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454629"
      ),
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(index(ri!nomination, "partnerPromotionDateHR", null)),
      true
    ),
    /*HR/Other Comments*/
    if(
      or(
        index(ri!nomination, "isVettingRequired", toboolean({})) = true,
        index(ri!nomination, "isAQR1or2", tostring(null)) = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185"
      ),
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(index(ri!nomination, "hrComments", null)),
      true
    )
  ),
  /*SUBMIT AND INSPECTIONS REVIEW*/
  if(
    ri!nomination.statusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4494074",
    if(
      isnull(ri!nomination.negativeInspectionFindings),
      false,
      if(
        ri!nomination.negativeInspectionFindings = true,
        a!isNotNullOrEmpty(ri!nomination.inspectionComments),
        true
      )
    ),
    true
  )
)
